{"endpoint":{"type":"keyword","script":{"source":"if (doc.containsKey('url.path') && doc['url.path'].size() > 0 && doc.containsKey('http.request.method') && doc['http.request.method'].size() > 0) {
  String method = doc['http.request.method'].value;
  boolean unmatched = doc.containsKey('http.response.status_code') && doc['http.response.status_code'].size() > 0
    && doc['http.response.status_code'].value == 404 && (!doc.containsKey('route') || doc['route'].size() == 0);
  if (unmatched) {
    emit(method + ' (ruta inexistente)');
  } else {
    String path = doc['url.path'].value;
    StringBuilder sb = new StringBuilder();
    for (String seg : path.splitOnToken('/')) {
      int n = seg.length();
      if (n == 0) { continue; }
      boolean isId = false;
      if (n == 36 && seg.charAt(8) == (char) '-' && seg.charAt(13) == (char) '-' && seg.charAt(18) == (char) '-' && seg.charAt(23) == (char) '-') {
        isId = true;
      } else {
        boolean digits = true;
        for (int i = 0; i < n; i++) {
          char c = seg.charAt(i);
          if (c < (char) '0' || c > (char) '9') { digits = false; break; }
        }
        isId = digits;
      }
      sb.append('/').append(isId ? ':id' : seg);
    }
    emit(method + ' ' + (sb.length() == 0 ? '/' : sb.toString()));
  }
}"}},"hora_del_dia":{"type":"long","script":{"source":"if (doc.containsKey('@timestamp') && doc['@timestamp'].size() > 0) {
  emit(doc['@timestamp'].value.withZoneSameInstant(ZoneId.of('America/Guatemala')).getHour());
}"}},"dia_semana":{"type":"long","script":{"source":"if (doc.containsKey('@timestamp') && doc['@timestamp'].size() > 0) {
  emit(doc['@timestamp'].value.withZoneSameInstant(ZoneId.of('America/Guatemala')).getDayOfWeek().getValue());
}"}}}

