{"title":"Actividad por día y hora: peticiones por celda (últimos 30 días, independiente del rango de tiempo)","type":"vega","aggs":[],"params":{"spec":"{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "autosize": {
    "type": "fit",
    "contains": "padding"
  },
  "padding": {
    "left": 4,
    "right": 4,
    "top": 4,
    "bottom": 4
  },
  "data": [
    {
      "name": "es",
      "url": {
        "index": "techsupport-logs-*",
        "body": {
          "size": 0,
          "query": {
            "bool": {
              "filter": [
                {
                  "term": {
                    "event.action": "http_request"
                  }
                },
                {
                  "range": {
                    "@timestamp": {
                      "gte": "now-30d",
                      "lte": "now"
                    }
                  }
                }
              ],
              "must_not": [
                {
                  "term": {
                    "http.request.method": "OPTIONS"
                  }
                },
                {
                  "terms": {
                    "url.path": [
                      "/health",
                      "/health/metrics",
                      "/metrics"
                    ]
                  }
                },
                {
                  "wildcard": {
                    "user_agent.original": "Elastic-Heartbeat*"
                  }
                }
              ]
            }
          },
          "runtime_mappings": {
            "celda": {
              "type": "long",
              "script": {
                "source": "if (doc.containsKey('@timestamp') && doc['@timestamp'].size() > 0) { def t = doc['@timestamp'].value.withZoneSameInstant(ZoneId.of('America/Guatemala')); emit(t.getDayOfWeek().getValue() * 100 + t.getHour()); }"
              }
            },
            "endpoint": {
              "type": "keyword",
              "script": {
                "source": "if (doc.containsKey('url.path') && doc['url.path'].size() > 0 && doc.containsKey('http.request.method') && doc['http.request.method'].size() > 0) {\n  String method = doc['http.request.method'].value;\n  boolean unmatched = doc.containsKey('http.response.status_code') && doc['http.response.status_code'].size() > 0\n    && doc['http.response.status_code'].value == 404 && (!doc.containsKey('route') || doc['route'].size() == 0);\n  if (unmatched) {\n    emit(method + ' (ruta inexistente)');\n  } else {\n    String path = doc['url.path'].value;\n    StringBuilder sb = new StringBuilder();\n    for (String seg : path.splitOnToken('/')) {\n      int n = seg.length();\n      if (n == 0) { continue; }\n      boolean isId = false;\n      if (n == 36 && seg.charAt(8) == (char) '-' && seg.charAt(13) == (char) '-' && seg.charAt(18) == (char) '-' && seg.charAt(23) == (char) '-') {\n        isId = true;\n      } else {\n        boolean digits = true;\n        for (int i = 0; i < n; i++) {\n          char c = seg.charAt(i);\n          if (c < (char) '0' || c > (char) '9') { digits = false; break; }\n        }\n        isId = digits;\n      }\n      sb.append('/').append(isId ? ':id' : seg);\n    }\n    emit(method + ' ' + (sb.length() == 0 ? '/' : sb.toString()));\n  }\n}"
              }
            }
          },
          "aggs": {
            "celdas": {
              "terms": {
                "field": "celda",
                "size": 200
              },
              "aggs": {
                "err": {
                  "filter": {
                    "range": {
                      "http.response.status_code": {
                        "gte": 500
                      }
                    }
                  }
                },
                "ep": {
                  "terms": {
                    "field": "endpoint",
                    "size": 3
                  }
                }
              }
            }
          }
        }
      },
      "format": {
        "property": "aggregations.celdas.buckets"
      },
      "transform": [
        {
          "type": "formula",
          "as": "k",
          "expr": "datum.key"
        },
        {
          "type": "formula",
          "as": "n",
          "expr": "datum.doc_count"
        },
        {
          "type": "formula",
          "as": "err",
          "expr": "datum.err.doc_count"
        },
        {
          "type": "formula",
          "as": "e1",
          "expr": "datum.ep.buckets.length > 0 ? datum.ep.buckets[0].key + ' (' + datum.ep.buckets[0].doc_count + ')' : '—'"
        },
        {
          "type": "formula",
          "as": "e2",
          "expr": "datum.ep.buckets.length > 1 ? datum.ep.buckets[1].key + ' (' + datum.ep.buckets[1].doc_count + ')' : '—'"
        },
        {
          "type": "formula",
          "as": "e3",
          "expr": "datum.ep.buckets.length > 2 ? datum.ep.buckets[2].key + ' (' + datum.ep.buckets[2].doc_count + ')' : '—'"
        }
      ]
    },
    {
      "name": "grid",
      "transform": [
        {
          "type": "sequence",
          "start": 0,
          "stop": 168,
          "as": "i"
        },
        {
          "type": "formula",
          "as": "dia",
          "expr": "floor(datum.i / 24) + 1"
        },
        {
          "type": "formula",
          "as": "hora",
          "expr": "datum.i % 24"
        },
        {
          "type": "formula",
          "as": "k",
          "expr": "datum.dia * 100 + datum.hora"
        },
        {
          "type": "lookup",
          "from": "es",
          "key": "k",
          "fields": [
            "k"
          ],
          "values": [
            "n",
            "err",
            "e1",
            "e2",
            "e3"
          ],
          "as": [
            "n0",
            "err0",
            "e10",
            "e20",
            "e30"
          ]
        },
        {
          "type": "formula",
          "as": "n",
          "expr": "datum.n0 || 0"
        },
        {
          "type": "formula",
          "as": "err",
          "expr": "datum.err0 || 0"
        },
        {
          "type": "formula",
          "as": "e1",
          "expr": "datum.e10 || '—'"
        },
        {
          "type": "formula",
          "as": "e2",
          "expr": "datum.e20 || '—'"
        },
        {
          "type": "formula",
          "as": "e3",
          "expr": "datum.e30 || '—'"
        }
      ]
    }
  ],
  "scales": [
    {
      "name": "x",
      "type": "band",
      "domain": {
        "data": "grid",
        "field": "hora",
        "sort": true
      },
      "range": "width",
      "paddingInner": 0.04
    },
    {
      "name": "y",
      "type": "band",
      "domain": {
        "data": "grid",
        "field": "dia",
        "sort": true
      },
      "range": "height",
      "paddingInner": 0.06
    },
    {
      "name": "color",
      "type": "quantize",
      "domain": {
        "data": "grid",
        "field": "n"
      },
      "range": [
        "#DCE8F6",
        "#B5D1EE",
        "#80B0E0",
        "#4A87C8",
        "#1F5FA6"
      ],
      "zero": true
    }
  ],
  "axes": [
    {
      "orient": "left",
      "scale": "y",
      "ticks": false,
      "domain": false,
      "labelPadding": 8,
      "encode": {
        "labels": {
          "update": {
            "text": {
              "signal": "[\"Lunes\",\"Martes\",\"Miércoles\",\"Jueves\",\"Viernes\",\"Sábado\",\"Domingo\"][datum.value - 1]"
            }
          }
        }
      }
    },
    {
      "orient": "bottom",
      "scale": "x",
      "ticks": false,
      "domain": false,
      "title": "Hora del día (Guatemala)",
      "encode": {
        "labels": {
          "update": {
            "text": {
              "signal": "(datum.value < 10 ? '0' : '') + datum.value"
            }
          }
        }
      }
    }
  ],
  "legends": [
    {
      "fill": "color",
      "orient": "right",
      "title": "Peticiones por celda",
      "format": ",.0f",
      "symbolType": "square"
    }
  ],
  "marks": [
    {
      "type": "rect",
      "from": {
        "data": "grid"
      },
      "encode": {
        "update": {
          "x": {
            "scale": "x",
            "field": "hora"
          },
          "width": {
            "scale": "x",
            "band": 1
          },
          "y": {
            "scale": "y",
            "field": "dia"
          },
          "height": {
            "scale": "y",
            "band": 1
          },
          "fill": {
            "scale": "color",
            "field": "n"
          },
          "tooltip": {
            "signal": "{'Día': [\"Lunes\",\"Martes\",\"Miércoles\",\"Jueves\",\"Viernes\",\"Sábado\",\"Domingo\"][datum.dia - 1], 'Hora': (datum.hora < 10 ? '0' : '') + datum.hora + ':00', 'Peticiones': format(datum.n, ',d'), 'Errores 5xx': format(datum.err, ',d'), 'Endpoint #1': datum.e1, 'Endpoint #2': datum.e2, 'Endpoint #3': datum.e3}"
          }
        }
      }
    }
  ]
}"}}
